<?php $left=placesLeft($event);?><article class="event-card"><a href="event.php?id=<?=(int)$event['event_id']?>"><div class="card-art"><?php if(empty($lowData)):?><img src="<?=e(eventArtwork($event))?>" alt="" loading="lazy"><?php endif;?><span class="card-category"><?=e($event['category'])?></span><div class="card-date"><strong><?=e(date('d',strtotime($event['start_time'])))?></strong><span><?=e(strtoupper(date('M',strtotime($event['start_time']))))?></span></div><?php if($left===0):?><span class="sold-out">Waiting list open</span><?php endif;?></div><div class="card-body"><p class="card-host"><?=e(organisationName($event))?></p><h3><?=e($event['title'])?></h3><p class="card-location"><?=e($event['location'])?></p><div class="card-bottom"><span><?=e(date('D · H:i',strtotime($event['start_time'])))?></span><span class="<?=$left===0?'muted':'availability'?>"><?=$left===0?'Join waitlist':$left.' spots left'?> <span aria-hidden="true">↗</span></span></div></div></a></article>
